with seed as (
  select * from jsonb_to_recordset('[{"id":"g11-math-authored-01","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(0) bằng bao nhiêu?","option_a":"0","option_b":"-1","option_c":"-√3/2","option_d":"-√2/2","correct_option":"A","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(0) = 0."},{"id":"g11-math-authored-02","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(π/6) bằng bao nhiêu?","option_a":"-√2/2","option_b":"-1/2","option_c":"0","option_d":"1/2","correct_option":"D","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(π/6) = 1/2."},{"id":"g11-math-authored-03","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(π/4) bằng bao nhiêu?","option_a":"1/2","option_b":"√3/2","option_c":"√2/2","option_d":"0","correct_option":"C","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(π/4) = √2/2."},{"id":"g11-math-authored-04","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(π/3) bằng bao nhiêu?","option_a":"-√2/2","option_b":"√3/2","option_c":"-1","option_d":"-√3/2","correct_option":"B","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(π/3) = √3/2."},{"id":"g11-math-authored-05","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(π/2) bằng bao nhiêu?","option_a":"1","option_b":"-√2/2","option_c":"-1/2","option_d":"0","correct_option":"A","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(π/2) = 1."},{"id":"g11-math-authored-06","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(2π/3) bằng bao nhiêu?","option_a":"0","option_b":"1/2","option_c":"√2/2","option_d":"√3/2","correct_option":"D","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(2π/3) = √3/2."},{"id":"g11-math-authored-07","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(3π/4) bằng bao nhiêu?","option_a":"-√3/2","option_b":"-√2/2","option_c":"√2/2","option_d":"-1","correct_option":"C","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(3π/4) = √2/2."},{"id":"g11-math-authored-08","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(5π/6) bằng bao nhiêu?","option_a":"0","option_b":"1/2","option_c":"-√2/2","option_d":"-1/2","correct_option":"B","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(5π/6) = 1/2."},{"id":"g11-math-authored-09","topic":"Hàm số lượng giác","prompt":"Giá trị của sin(π) bằng bao nhiêu?","option_a":"0","option_b":"1/2","option_c":"√2/2","option_d":"√3/2","correct_option":"A","explanation":"Dựa vào các giá trị lượng giác của góc đặc biệt, sin(π) = 0."},{"id":"g11-math-authored-10","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 2, công sai d = 3. Tính u_4.","option_a":"14","option_b":"8","option_c":"15","option_d":"11","correct_option":"D","explanation":"uₙ = u₁ + (n − 1)d = 2 + (4 − 1)·3 = 11."},{"id":"g11-math-authored-11","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 3, công sai d = 4. Tính u_5.","option_a":"15","option_b":"24","option_c":"19","option_d":"23","correct_option":"C","explanation":"uₙ = u₁ + (n − 1)d = 3 + (5 − 1)·4 = 19."},{"id":"g11-math-authored-12","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 4, công sai d = 5. Tính u_6.","option_a":"35","option_b":"29","option_c":"34","option_d":"24","correct_option":"B","explanation":"uₙ = u₁ + (n − 1)d = 4 + (6 − 1)·5 = 29."},{"id":"g11-math-authored-13","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 5, công sai d = 2. Tính u_7.","option_a":"17","option_b":"19","option_c":"15","option_d":"20","correct_option":"A","explanation":"uₙ = u₁ + (n − 1)d = 5 + (7 − 1)·2 = 17."},{"id":"g11-math-authored-14","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 6, công sai d = 3. Tính u_8.","option_a":"30","option_b":"24","option_c":"31","option_d":"27","correct_option":"D","explanation":"uₙ = u₁ + (n − 1)d = 6 + (8 − 1)·3 = 27."},{"id":"g11-math-authored-15","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 7, công sai d = 4. Tính u_9.","option_a":"35","option_b":"44","option_c":"39","option_d":"43","correct_option":"C","explanation":"uₙ = u₁ + (n − 1)d = 7 + (9 − 1)·4 = 39."},{"id":"g11-math-authored-16","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 8, công sai d = 5. Tính u_10.","option_a":"59","option_b":"53","option_c":"58","option_d":"48","correct_option":"B","explanation":"uₙ = u₁ + (n − 1)d = 8 + (10 − 1)·5 = 53."},{"id":"g11-math-authored-17","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 9, công sai d = 2. Tính u_11.","option_a":"29","option_b":"31","option_c":"27","option_d":"32","correct_option":"A","explanation":"uₙ = u₁ + (n − 1)d = 9 + (11 − 1)·2 = 29."},{"id":"g11-math-authored-18","topic":"Cấp số cộng","prompt":"Một cấp số cộng có u₁ = 10, công sai d = 3. Tính u_12.","option_a":"46","option_b":"40","option_c":"47","option_d":"43","correct_option":"D","explanation":"uₙ = u₁ + (n − 1)d = 10 + (12 − 1)·3 = 43."},{"id":"g11-math-authored-19","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (4n + 4) / (2n + 7).","option_a":"1","option_b":"4","option_c":"2","option_d":"3","correct_option":"C","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 4/2 = 2."},{"id":"g11-math-authored-20","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (6n + 5) / (2n + 9).","option_a":"5","option_b":"3","option_c":"4","option_d":"2","correct_option":"B","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 6/2 = 3."},{"id":"g11-math-authored-21","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (8n + 6) / (2n + 11).","option_a":"4","option_b":"5","option_c":"3","option_d":"6","correct_option":"A","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 8/2 = 4."},{"id":"g11-math-authored-22","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (10n + 7) / (2n + 13).","option_a":"6","option_b":"4","option_c":"7","option_d":"5","correct_option":"D","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 10/2 = 5."},{"id":"g11-math-authored-23","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (12n + 8) / (2n + 15).","option_a":"5","option_b":"8","option_c":"6","option_d":"7","correct_option":"C","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 12/2 = 6."},{"id":"g11-math-authored-24","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (14n + 9) / (2n + 17).","option_a":"9","option_b":"7","option_c":"8","option_d":"6","correct_option":"B","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 14/2 = 7."},{"id":"g11-math-authored-25","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (16n + 10) / (2n + 19).","option_a":"8","option_b":"9","option_c":"7","option_d":"10","correct_option":"A","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 16/2 = 8."},{"id":"g11-math-authored-26","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (18n + 11) / (2n + 21).","option_a":"10","option_b":"8","option_c":"11","option_d":"9","correct_option":"D","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 18/2 = 9."},{"id":"g11-math-authored-27","topic":"Giới hạn dãy số","prompt":"Tính lim khi n → +∞ của (20n + 12) / (2n + 23).","option_a":"9","option_b":"12","option_c":"10","option_d":"11","correct_option":"C","explanation":"Chia tử và mẫu cho n; các hạng chứa 1/n tiến về 0, nên giới hạn bằng 20/2 = 10."},{"id":"g11-math-authored-28","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 2x − 4. Giá trị f''(2) bằng bao nhiêu?","option_a":"9","option_b":"6","option_c":"8","option_d":"4","correct_option":"B","explanation":"f''(x) = 2x + 2; do đó f''(2) = 2·2 + 2 = 6."},{"id":"g11-math-authored-29","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 3x − 4. Giá trị f''(3) bằng bao nhiêu?","option_a":"9","option_b":"11","option_c":"7","option_d":"15","correct_option":"A","explanation":"f''(x) = 2x + 3; do đó f''(3) = 2·3 + 3 = 9."},{"id":"g11-math-authored-30","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 4x − 4. Giá trị f''(4) bằng bao nhiêu?","option_a":"14","option_b":"10","option_c":"23","option_d":"12","correct_option":"D","explanation":"f''(x) = 2x + 4; do đó f''(4) = 2·4 + 4 = 12."},{"id":"g11-math-authored-31","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 5x − 4. Giá trị f''(5) bằng bao nhiêu?","option_a":"13","option_b":"33","option_c":"15","option_d":"17","correct_option":"C","explanation":"f''(x) = 2x + 5; do đó f''(5) = 2·5 + 5 = 15."},{"id":"g11-math-authored-32","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 1x − 4. Giá trị f''(6) bằng bao nhiêu?","option_a":"40","option_b":"13","option_c":"15","option_d":"11","correct_option":"B","explanation":"f''(x) = 2x + 1; do đó f''(6) = 2·6 + 1 = 13."},{"id":"g11-math-authored-33","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 2x − 4. Giá trị f''(7) bằng bao nhiêu?","option_a":"16","option_b":"18","option_c":"14","option_d":"54","correct_option":"A","explanation":"f''(x) = 2x + 2; do đó f''(7) = 2·7 + 2 = 16."},{"id":"g11-math-authored-34","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 3x − 4. Giá trị f''(8) bằng bao nhiêu?","option_a":"21","option_b":"17","option_c":"70","option_d":"19","correct_option":"D","explanation":"f''(x) = 2x + 3; do đó f''(8) = 2·8 + 3 = 19."},{"id":"g11-math-authored-35","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 4x − 4. Giá trị f''(9) bằng bao nhiêu?","option_a":"20","option_b":"88","option_c":"22","option_d":"24","correct_option":"C","explanation":"f''(x) = 2x + 4; do đó f''(9) = 2·9 + 4 = 22."},{"id":"g11-math-authored-36","topic":"Đạo hàm","prompt":"Cho f(x) = x² + 5x − 4. Giá trị f''(10) bằng bao nhiêu?","option_a":"108","option_b":"25","option_c":"27","option_d":"23","correct_option":"B","explanation":"f''(x) = 2x + 5; do đó f''(10) = 2·10 + 5 = 25."},{"id":"g11-math-authored-37","topic":"Hình học không gian","prompt":"Nếu hai điểm phân biệt của một đường thẳng cùng thuộc một mặt phẳng thì đường thẳng đó có quan hệ nào với mặt phẳng?","option_a":"Nằm trong mặt phẳng","option_b":"Song song với mặt phẳng","option_c":"Vuông góc với mặt phẳng","option_d":"Không có điểm chung với mặt phẳng","correct_option":"A","explanation":"Một mặt phẳng chứa hai điểm phân biệt của đường thẳng thì chứa cả đường thẳng qua hai điểm ấy."},{"id":"g11-math-authored-38","topic":"Hình học không gian","prompt":"Hai mặt phẳng phân biệt có một điểm chung thì giao tuyến của chúng là gì?","option_a":"Một điểm duy nhất","option_b":"Một đoạn thẳng hữu hạn","option_c":"Hai đường thẳng song song","option_d":"Một đường thẳng","correct_option":"D","explanation":"Hai mặt phẳng phân biệt nếu có điểm chung thì giao nhau theo một đường thẳng."},{"id":"g11-math-authored-39","topic":"Hình học không gian","prompt":"Qua một điểm nằm ngoài một đường thẳng, có bao nhiêu mặt phẳng chứa đường thẳng và điểm đó?","option_a":"Đúng hai mặt phẳng","option_b":"Vô số mặt phẳng","option_c":"Đúng một mặt phẳng","option_d":"Không có mặt phẳng nào","correct_option":"C","explanation":"Một đường thẳng và một điểm không thuộc nó xác định duy nhất một mặt phẳng."},{"id":"g11-math-authored-40","topic":"Hình học không gian","prompt":"Hai đường thẳng song song phân biệt xác định bao nhiêu mặt phẳng?","option_a":"Vô số mặt phẳng","option_b":"Đúng một mặt phẳng","option_c":"Không có mặt phẳng nào","option_d":"Đúng hai mặt phẳng","correct_option":"B","explanation":"Hai đường thẳng song song phân biệt cùng nằm trong đúng một mặt phẳng."},{"id":"g11-math-authored-41","topic":"Hình học không gian","prompt":"Nếu đường thẳng d song song với mặt phẳng (P) và d không nằm trong (P), d có bao nhiêu điểm chung với (P)?","option_a":"Không có điểm chung","option_b":"Một điểm chung","option_c":"Vô số điểm chung","option_d":"Hai điểm chung","correct_option":"A","explanation":"Đường thẳng song song với mặt phẳng và không nằm trong mặt phẳng thì không cắt mặt phẳng."},{"id":"g11-math-authored-42","topic":"Hình học không gian","prompt":"Hai mặt phẳng song song bị cắt bởi mặt phẳng thứ ba thì hai giao tuyến có quan hệ nào?","option_a":"Cắt nhau vuông góc","option_b":"Trùng nhau","option_c":"Chéo nhau","option_d":"Song song với nhau","correct_option":"D","explanation":"Các giao tuyến của một mặt phẳng với hai mặt phẳng song song là hai đường thẳng song song."},{"id":"g11-math-authored-43","topic":"Hình học không gian","prompt":"Đường thẳng vuông góc với mặt phẳng tại H vuông góc với đường nào trong mặt phẳng?","option_a":"Chỉ đường thẳng không đi qua H","option_b":"Không đường thẳng nào","option_c":"Mọi đường thẳng của mặt phẳng đi qua H","option_d":"Chỉ đường thẳng song song với nó","correct_option":"C","explanation":"Theo định nghĩa, đường thẳng vuông góc mặt phẳng tại H vuông góc mọi đường trong mặt phẳng đi qua H."},{"id":"g11-math-authored-44","topic":"Hình học không gian","prompt":"Nếu đường thẳng a song song với đường thẳng b nằm trong mặt phẳng (P), đồng thời a không thuộc (P), thì a và (P) có quan hệ nào?","option_a":"Nằm trong mặt phẳng","option_b":"Song song","option_c":"Vuông góc","option_d":"Cắt tại hai điểm","correct_option":"B","explanation":"Đường thẳng song song với một đường nằm trong mặt phẳng và không nằm trong mặt phẳng ấy thì song song với mặt phẳng."},{"id":"g11-math-authored-45","topic":"Hình học không gian","prompt":"Hai mặt phẳng phân biệt cùng vuông góc với một đường thẳng thì có quan hệ nào?","option_a":"Song song với nhau","option_b":"Vuông góc với nhau","option_c":"Cắt nhau theo đường thẳng vuông góc với đường đã cho","option_d":"Trùng nhau","correct_option":"A","explanation":"Hai mặt phẳng cùng vuông góc với một đường thẳng thì song song với nhau."}]'::jsonb) as q(
    id text, topic text, prompt text, option_a text, option_b text,
    option_c text, option_d text, correct_option text, explanation text
  )
)
insert into public.mentor_questions(
  id, code, subject_id, grade, chapter, topic, textbook, prompt,
  option_a, option_b, option_c, option_d, correct_option, explanation,
  difficulty, points, source, author, license, status
)
select id, upper(replace(id, '-', '_')), 'math', 11, topic, topic,
  'Kết nối tri thức', prompt, option_a, option_b, option_c, option_d,
  correct_option, explanation, 'EASY', 10,
  'AI Mentor tự biên soạn theo quy tắc Toán 11; đáp án kiểm tra được',
  'AI Mentor', 'Nội bộ', 'PUBLISHED'
from seed
on conflict (id) do nothing;

do $$
declare inserted_count integer;
begin
  select count(*) into inserted_count from public.mentor_questions
  where id between 'g11-math-authored-01' and 'g11-math-authored-45'
    and status = 'PUBLISHED';
  if inserted_count <> 45 then
    raise exception 'Expected 45 published Math 11 additions; found %', inserted_count;
  end if;
end $$;
commit;
